// Map editor state: a working copy of the map, the active tool, selection and undo history.
// Everything the editor touches is plain JSON so maps can also be generated by other tools.

export const PERMIT_TYPES = ['freshman', 'upperclass', 'faculty', 'resident', 'visitor'];
export const LOT_COLORS = {
  freshman: '#D97706',
  upperclass: '#00573D',
  faculty: '#1E3A8A',
  resident: '#7C3AED',
  visitor: '#0D9488'
};
export const STALL_W = 23.4; // across the stall
export const STALL_L = 40.0; // stall depth

export const TOOLS = [
  { id: 'select', label: 'Select', key: 'V', hint: 'Click a shape to select it. Drag to move it, drag a corner to reshape it, Delete removes it. Drag empty space to pan.' },
  { id: 'lot', label: 'Lot', key: 'L', hint: 'Click to add corners. Enter or double-click to finish, Backspace removes the last point, Esc cancels.' },
  { id: 'stall', label: 'Stall row', key: 'T', hint: 'Drag a line inside a lot to fill it with stalls; a single click places one. [ and ] rotate the selected stall.' },
  { id: 'building', label: 'Building', key: 'B', hint: 'Click to trace the building outline. Buildings are solid walls.' },
  { id: 'grass', label: 'Grass', key: 'G', hint: 'Trace a grass area. Cars can drive on it but get an off-road strike.' },
  { id: 'solid', label: 'Solid', key: 'O', hint: 'Trace a solid area (curb, wall, fence). Cars cannot drive through it.' },
  { id: 'ped', label: 'Ped path', key: 'P', hint: 'Click points along a sidewalk, Enter to finish. A student walks it back and forth.' },
  { id: 'spawn', label: 'Spawn', key: 'S', hint: 'Click where the car starts this mission, drag to aim it.' },
  { id: 'delete', label: 'Delete', key: 'X', hint: 'Click any shape to delete it.' }
];

const POLY_TOOLS = new Set(['lot', 'building', 'grass', 'solid', 'ped']);
const EDIT_KEYS = ['zones', 'lots', 'buildings', 'pedestrian_paths', 'spawn', 'destinations', 'use_legacy_collision_tiles'];
const MAX_UNDO = 40;

export function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const xi = poly[i][0], yi = poly[i][1];
    const xj = poly[j][0], yj = poly[j][1];
    if (((yi > y) !== (yj > y)) && (x < ((xj - xi) * (y - yi)) / (yj - yi + 1e-9) + xi)) inside = !inside;
  }
  return inside;
}

export function distToSegment(px, py, a, b) {
  const dx = b[0] - a[0], dy = b[1] - a[1];
  const l2 = dx * dx + dy * dy;
  let t = l2 ? ((px - a[0]) * dx + (py - a[1]) * dy) / l2 : 0;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(px - (a[0] + t * dx), py - (a[1] + t * dy));
}

export function stallCorners(s) {
  const a = ((s.angle || 0) * Math.PI) / 180;
  const c = Math.cos(a), si = Math.sin(a);
  const hl = s.height / 2, hw = s.width / 2;
  return [[-hl, -hw], [hl, -hw], [hl, hw], [-hl, hw]].map(([lx, ly]) => [s.x + lx * c - ly * si, s.y + lx * si + ly * c]);
}

export function rectToPoly([x, y, w, h]) {
  return [[x, y], [x + w, y], [x + w, y + h], [x, y + h]];
}

function bboxOf(points) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const [x, y] of points) {
    if (x < minX) minX = x; if (y < minY) minY = y;
    if (x > maxX) maxX = x; if (y > maxY) maxY = y;
  }
  return [minX, minY, maxX - minX, maxY - minY];
}

const round1 = (v) => Math.round(v * 10) / 10;
const uid = (prefix) => `${prefix}_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;

export class EditorState {
  constructor(map, { camera, activeDestinationId = null, onChange = () => {} }) {
    // The working copy; trees, roads and traffic are shared (not editable) to keep this cheap
    this.map = { ...map };
    for (const k of EDIT_KEYS) {
      if (map[k] !== undefined) this.map[k] = structuredClone(map[k]);
    }
    if (!this.map.zones) this.map.zones = [];
    if (this.map.use_legacy_collision_tiles === undefined) this.map.use_legacy_collision_tiles = true;

    this.cam = { x: camera.x, y: camera.y, zoom: Math.min(camera.zoom, 1.4) };
    this.activeDestinationId = activeDestinationId;
    this.onChange = onChange;

    this.tool = 'select';
    this.traceTarget = null; // building index whose outline is being traced
    this.permit = 'upperclass';
    this.selection = null; // { kind: 'zone'|'lot'|'stall'|'building'|'ped'|'spawn', i, j? }
    this.draft = []; // points of the shape being drawn
    this.stallDrag = null; // { a: [x, y], b: [x, y] }
    this.drag = null;
    this.hover = null; // world-space cursor
    this.layers = { zones: true, lots: true, stalls: true, buildings: true, peds: true, legacy: false };
    this.undoStack = [];
    this.redoStack = [];
    this.dirty = false;
    this.message = null;
  }

  // ---------- history ----------
  snapshot() {
    const snap = {};
    for (const k of EDIT_KEYS) snap[k] = structuredClone(this.map[k]);
    return snap;
  }

  pushUndo() {
    this.undoStack.push(this.snapshot());
    if (this.undoStack.length > MAX_UNDO) this.undoStack.shift();
    this.redoStack = [];
    this.dirty = true;
  }

  restore(snap) {
    for (const k of EDIT_KEYS) this.map[k] = snap[k];
    this.selection = null;
    this.dirty = true;
  }

  undo() {
    if (!this.undoStack.length) return;
    this.redoStack.push(this.snapshot());
    this.restore(this.undoStack.pop());
    this.changed();
  }

  redo() {
    if (!this.redoStack.length) return;
    this.undoStack.push(this.snapshot());
    this.restore(this.redoStack.pop());
    this.changed();
  }

  changed() {
    this.onChange();
  }

  flash(text) {
    this.message = { text, at: Date.now() };
    this.changed();
  }

  // ---------- tools ----------
  setTool(id) {
    this.tool = id;
    this.traceTarget = null;
    this.draft = [];
    this.stallDrag = null;
    if (id !== 'select') this.selection = null;
    this.changed();
  }

  spawnTarget() {
    const dest = (this.map.destinations || []).find((d) => d.id === this.activeDestinationId);
    return dest?.spawn ? { obj: dest, label: `${dest.name} start` } : { obj: this.map, label: 'Default start' };
  }

  // ---------- hit testing ----------
  handleRadius() {
    return 7 / this.cam.zoom;
  }

  shapePoints(sel) {
    if (!sel) return null;
    const m = this.map;
    switch (sel.kind) {
      case 'zone': return m.zones[sel.i]?.polygon;
      case 'lot': return m.lots[sel.i]?.polygon;
      case 'building': {
        const b = m.buildings[sel.i];
        return b ? (b.polygon && b.polygon.length >= 3 ? b.polygon : null) : null;
      }
      case 'ped': return m.pedestrian_paths[sel.i]?.points;
      default: return null;
    }
  }

  hitTest(wx, wy) {
    const m = this.map, L = this.layers;
    const tol = 6 / this.cam.zoom;

    const sp = this.spawnTarget().obj.spawn;
    if (sp && Math.hypot(wx - sp.x, wy - sp.y) < 14 / this.cam.zoom + 6) return { kind: 'spawn' };

    if (L.stalls && L.lots) {
      for (let i = m.lots.length - 1; i >= 0; i--) {
        const stalls = m.lots[i].stalls || [];
        for (let j = stalls.length - 1; j >= 0; j--) {
          const s = stalls[j];
          if (Math.abs(s.x - wx) > 30 || Math.abs(s.y - wy) > 30) continue;
          if (pointInPoly(wx, wy, stallCorners(s))) return { kind: 'stall', i, j };
        }
      }
    }
    if (L.peds) {
      for (let i = m.pedestrian_paths.length - 1; i >= 0; i--) {
        const pts = m.pedestrian_paths[i].points;
        for (let k = 0; k < pts.length - 1; k++) {
          if (distToSegment(wx, wy, pts[k], pts[k + 1]) < tol) return { kind: 'ped', i };
        }
      }
    }
    if (L.buildings) {
      for (let i = m.buildings.length - 1; i >= 0; i--) {
        const b = m.buildings[i];
        const poly = b.polygon && b.polygon.length >= 3 ? b.polygon : rectToPoly(b.rect);
        if (pointInPoly(wx, wy, poly)) return { kind: 'building', i };
      }
    }
    if (L.zones) {
      for (let i = m.zones.length - 1; i >= 0; i--) {
        if (pointInPoly(wx, wy, m.zones[i].polygon)) return { kind: 'zone', i };
      }
    }
    if (L.lots) {
      for (let i = m.lots.length - 1; i >= 0; i--) {
        if (m.lots[i].polygon && pointInPoly(wx, wy, m.lots[i].polygon)) return { kind: 'lot', i };
      }
    }
    return null;
  }

  vertexAt(wx, wy) {
    const pts = this.shapePoints(this.selection);
    if (!pts) return -1;
    const r = this.handleRadius() * 1.6;
    for (let k = 0; k < pts.length; k++) {
      if (Math.hypot(pts[k][0] - wx, pts[k][1] - wy) <= r) return k;
    }
    return -1;
  }

  // ---------- mutations ----------
  translateSelection(dx, dy) {
    const sel = this.selection, m = this.map;
    if (!sel) return;
    const shift = (pts) => { for (const p of pts) { p[0] += dx; p[1] += dy; } };
    if (sel.kind === 'zone') shift(m.zones[sel.i].polygon);
    else if (sel.kind === 'ped') shift(m.pedestrian_paths[sel.i].points);
    else if (sel.kind === 'lot') {
      const lot = m.lots[sel.i];
      shift(lot.polygon);
      for (const s of lot.stalls || []) { s.x += dx; s.y += dy; }
    } else if (sel.kind === 'building') {
      const b = m.buildings[sel.i];
      if (b.polygon) shift(b.polygon);
      b.rect[0] += dx; b.rect[1] += dy;
    } else if (sel.kind === 'stall') {
      const s = m.lots[sel.i].stalls[sel.j];
      s.x += dx; s.y += dy;
    } else if (sel.kind === 'spawn') {
      const sp = this.spawnTarget().obj.spawn;
      sp.x += dx; sp.y += dy;
    }
  }

  roundSelection() {
    const pts = this.shapePoints(this.selection);
    if (pts) for (const p of pts) { p[0] = round1(p[0]); p[1] = round1(p[1]); }
    const sel = this.selection;
    if (sel?.kind === 'building') {
      const b = this.map.buildings[sel.i];
      if (b.polygon && b.polygon.length >= 3) b.rect = bboxOf(b.polygon).map(round1);
      else b.rect = b.rect.map(round1);
    }
    if (sel?.kind === 'stall') {
      const s = this.map.lots[sel.i].stalls[sel.j];
      s.x = round1(s.x); s.y = round1(s.y);
    }
    if (sel?.kind === 'lot') for (const s of this.map.lots[sel.i].stalls || []) { s.x = round1(s.x); s.y = round1(s.y); }
    if (sel?.kind === 'spawn') {
      const sp = this.spawnTarget().obj.spawn;
      sp.x = round1(sp.x); sp.y = round1(sp.y);
    }
  }

  deleteSelection(sel = this.selection) {
    if (!sel || sel.kind === 'spawn') return;
    const m = this.map;
    this.pushUndo();
    if (sel.kind === 'zone') m.zones.splice(sel.i, 1);
    else if (sel.kind === 'lot') {
      const id = m.lots[sel.i].id;
      m.lots.splice(sel.i, 1);
      for (const d of m.destinations || []) d.target_lot_ids = (d.target_lot_ids || []).filter((x) => x !== id);
    } else if (sel.kind === 'stall') m.lots[sel.i].stalls.splice(sel.j, 1);
    else if (sel.kind === 'building') {
      const id = m.buildings[sel.i].id;
      if ((m.destinations || []).some((d) => d.building_id === id)) {
        this.undoStack.pop();
        this.flash('That building is a mission destination, so it can\'t be deleted. Reshape it instead.');
        return;
      }
      m.buildings.splice(sel.i, 1);
    } else if (sel.kind === 'ped') m.pedestrian_paths.splice(sel.i, 1);
    this.selection = null;
    this.changed();
  }

  rotateSelectedStall(deg) {
    const sel = this.selection;
    if (sel?.kind !== 'stall') return;
    this.pushUndo();
    const s = this.map.lots[sel.i].stalls[sel.j];
    s.angle = round1((((s.angle || 0) + deg) % 360 + 360) % 360);
    this.changed();
  }

  updateSelected(patch) {
    const sel = this.selection, m = this.map;
    if (!sel) return;
    this.pushUndo();
    if (sel.kind === 'zone') Object.assign(m.zones[sel.i], patch);
    else if (sel.kind === 'building') Object.assign(m.buildings[sel.i], patch);
    else if (sel.kind === 'ped') Object.assign(m.pedestrian_paths[sel.i], patch);
    else if (sel.kind === 'stall') Object.assign(m.lots[sel.i].stalls[sel.j], patch);
    else if (sel.kind === 'spawn') Object.assign(this.spawnTarget().obj.spawn, patch);
    else if (sel.kind === 'lot') {
      const lot = m.lots[sel.i];
      const { applyToStalls, ...rest } = patch;
      Object.assign(lot, rest);
      if (rest.lot_type) {
        lot.permit_type = rest.lot_type;
        lot.color = LOT_COLORS[rest.lot_type] || lot.color;
        if (applyToStalls) for (const s of lot.stalls || []) s.stall_type = rest.lot_type;
      }
    }
    this.changed();
  }

  finishDraft() {
    const t = this.tool;
    // Double-click adds the same point twice; drop near-duplicates
    const pts = [];
    for (const [x, y] of this.draft) {
      const prev = pts[pts.length - 1];
      if (!prev || Math.hypot(prev[0] - x, prev[1] - y) > 2 / this.cam.zoom) pts.push([round1(x), round1(y)]);
    }
    const m = this.map;
    const minPts = t === 'ped' ? 2 : 3;
    if (pts.length < minPts) {
      this.flash(`Need at least ${minPts} points.`);
      return;
    }
    this.pushUndo();
    if (t === 'grass' || t === 'solid') {
      m.zones.push({ id: uid('zone'), type: t, polygon: pts, name: '' });
      this.selection = { kind: 'zone', i: m.zones.length - 1 };
    } else if (t === 'lot') {
      const n = m.lots.filter((l) => l.id.startsWith('lot_custom')).length + 1;
      m.lots.push({ id: uid('lot_custom'), name: `New Lot ${n}`, lot_type: this.permit, permit_type: this.permit, color: LOT_COLORS[this.permit], polygon: pts, stalls: [] });
      this.selection = { kind: 'lot', i: m.lots.length - 1 };
    } else if (t === 'building' && this.traceTarget !== null && m.buildings[this.traceTarget]) {
      const b = m.buildings[this.traceTarget];
      b.polygon = pts;
      b.rect = bboxOf(pts).map(round1);
      this.selection = { kind: 'building', i: this.traceTarget };
      this.traceTarget = null;
      this.tool = 'select';
      this.flash(`${b.name} now has an exact hitbox.`);
    } else if (t === 'building') {
      const n = m.buildings.filter((b) => b.id.startsWith('b_custom')).length + 1;
      m.buildings.push({ id: uid('b_custom'), name: `New Building ${n}`, rect: bboxOf(pts).map(round1), polygon: pts, color: '#334155', label: `New Building ${n}` });
      this.selection = { kind: 'building', i: m.buildings.length - 1 };
    } else if (t === 'ped') {
      m.pedestrian_paths.push({ id: uid('ped'), points: pts, speed: 22.0, shirt: '#00573D' });
      this.selection = { kind: 'ped', i: m.pedestrian_paths.length - 1 };
    }
    this.draft = [];
    this.changed();
  }

  // Start tracing a real outline for an existing building (keeps its id, so missions still point at it)
  startTrace(i) {
    this.tool = 'building';
    this.draft = [];
    this.traceTarget = i;
    this.flash(`Click around ${this.map.buildings[i].name}'s walls, then press Enter.`);
  }

  // Lot that should receive stalls placed around (x, y): the one containing it, else the nearest one close by
  lotForPoint(x, y) {
    const lots = this.map.lots;
    for (let i = lots.length - 1; i >= 0; i--) if (lots[i].polygon && pointInPoly(x, y, lots[i].polygon)) return i;
    let best = -1, bestD = 120;
    lots.forEach((l, i) => {
      if (!l.polygon) return;
      for (let k = 0; k < l.polygon.length; k++) {
        const d = distToSegment(x, y, l.polygon[k], l.polygon[(k + 1) % l.polygon.length]);
        if (d < bestD) { bestD = d; best = i; }
      }
    });
    return best;
  }

  placeStalls(a, b) {
    const len = Math.hypot(b[0] - a[0], b[1] - a[1]);
    const mid = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2];
    const li = this.lotForPoint(mid[0], mid[1]);
    if (li < 0) {
      this.flash('Stalls must go inside a lot. Draw a lot first.');
      return;
    }
    const lot = this.map.lots[li];
    lot.stalls = lot.stalls || [];
    this.pushUndo();
    const dirDeg = (Math.atan2(b[1] - a[1], b[0] - a[0]) * 180) / Math.PI;
    const angle = round1(((dirDeg + 90) % 360 + 360) % 360); // stall depth runs across the row
    const count = len < STALL_W ? 1 : Math.floor(len / STALL_W);
    const ux = len ? (b[0] - a[0]) / len : 0, uy = len ? (b[1] - a[1]) / len : 0;
    const startOff = len < STALL_W ? 0 : STALL_W / 2;
    const base = Date.now().toString(36);
    for (let k = 0; k < count; k++) {
      const d = startOff + k * STALL_W;
      lot.stalls.push({
        id: `${lot.id}_e${base}_${k}`,
        lot_id: lot.id,
        x: round1(a[0] + ux * d),
        y: round1(a[1] + uy * d),
        width: STALL_W,
        height: STALL_L,
        angle: len < STALL_W ? 0 : angle,
        stall_type: this.permit
      });
    }
    this.selection = count === 1 ? { kind: 'stall', i: li, j: lot.stalls.length - 1 } : { kind: 'lot', i: li };
    this.flash(`Added ${count} stall${count === 1 ? '' : 's'} to ${lot.name}.`);
  }

  // ---------- pointer input (world coordinates) ----------
  pointerDown(wx, wy, { button = 0, shift = false } = {}) {
    if (button === 2 || button === 1) {
      this.drag = { type: 'pan', lastSx: null };
      return;
    }
    const t = this.tool;
    if (POLY_TOOLS.has(t)) {
      this.draft.push([wx, wy]);
      this.changed();
      return;
    }
    if (t === 'stall') {
      this.stallDrag = { a: [wx, wy], b: [wx, wy] };
      return;
    }
    if (t === 'spawn') {
      const target = this.spawnTarget().obj;
      this.pushUndo();
      target.spawn = { x: round1(wx), y: round1(wy), heading: target.spawn?.heading ?? 0 };
      this.selection = { kind: 'spawn' };
      this.drag = { type: 'aim' };
      this.changed();
      return;
    }
    if (t === 'delete') {
      const hit = this.hitTest(wx, wy);
      if (hit) this.deleteSelection(hit);
      return;
    }
    // select
    const v = this.vertexAt(wx, wy);
    if (v >= 0) {
      this.pushUndo();
      this.drag = { type: 'vertex', k: v };
      return;
    }
    const hit = this.hitTest(wx, wy);
    this.selection = hit;
    if (hit) {
      this.drag = { type: 'move', last: [wx, wy], moved: false };
    } else {
      this.drag = { type: 'pan', lastSx: null };
    }
    this.changed();
  }

  pointerMove(wx, wy) {
    this.hover = [wx, wy];
    const d = this.drag;
    if (this.stallDrag) this.stallDrag.b = [wx, wy];
    if (!d) return;
    if (d.type === 'vertex') {
      const pts = this.shapePoints(this.selection);
      if (pts) { pts[d.k][0] = wx; pts[d.k][1] = wy; }
    } else if (d.type === 'move') {
      if (!d.moved) { this.pushUndo(); d.moved = true; }
      this.translateSelection(wx - d.last[0], wy - d.last[1]);
      d.last = [wx, wy];
    } else if (d.type === 'aim') {
      const sp = this.spawnTarget().obj.spawn;
      if (Math.hypot(wx - sp.x, wy - sp.y) > 4) {
        sp.heading = round1((((Math.atan2(wy - sp.y, wx - sp.x) * 180) / Math.PI) % 360 + 360) % 360);
      }
    }
  }

  pointerUp() {
    if (this.stallDrag) {
      const { a, b } = this.stallDrag;
      this.stallDrag = null;
      this.placeStalls(a, b);
    }
    if (this.drag && this.drag.type !== 'pan') this.roundSelection();
    const wasEdit = this.drag && this.drag.type !== 'pan';
    this.drag = null;
    if (wasEdit) this.changed();
  }

  // Pan by a screen-space delta
  panScreen(dx, dy) {
    this.cam.x -= dx / this.cam.zoom;
    this.cam.y -= dy / this.cam.zoom;
  }

  zoomAt(factor, wx, wy) {
    const z = Math.max(0.15, Math.min(4, this.cam.zoom * factor));
    const k = 1 - this.cam.zoom / z;
    this.cam.x += (wx - this.cam.x) * k;
    this.cam.y += (wy - this.cam.y) * k;
    this.cam.zoom = z;
    this.changed();
  }

  // The full map to save: the original with the edited keys swapped in
  toMap() {
    return { ...this.map };
  }
}
